body.script:
const TARGET = "https://cdn.jsdelivr.net/gh/CloudMoonApp/web@main/portal-2604131056.html";
const $ = i => document.getElementById(i), err = $('err'); let signup = false;
async function h(t){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('nebula:'+t));return [...new Uint8Array(d)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function launch(){
  localStorage.setItem('nebula_in','1');
  $('card').style.display='none'; $('c').style.display='none';
  const params = new URLSearchParams(window.location.search); params.set("t", Date.now());
  const safeUrl = TARGET + "?" + params.toString();
  const l = `\x3Cscript>
    fetch("${safeUrl}").then(r=>r.text()).then(html=>{
      html=html.split('Cloud<span class="text-[#8b5cf6]">Moon</span>').join('Nebula <span class="text-[#8b5cf6]">Cloud Play</span>');
      html=html.split("<title>CloudMoon All-in-One</title>").join("<title>Nebula Cloud Play</title>");
      html=html.split("https://cloudmoonapp.com/favicon.ico").join("data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Cdefs%3E%3CradialGradient id='g' cx='30%25' cy='30%25'%3E%3Cstop offset='0' stop-color='%23ff8ad8'/%3E%3Cstop offset='.5' stop-color='%238a5cff'/%3E%3Cstop offset='1' stop-color='%231b3fa8'/%3E%3C/radialGradient%3E%3C/defs%3E%3Ccircle cx='16' cy='16' r='16' fill='url(%23g)'/%3E%3C/svg%3E");
      html=html.split('<h2 class="text-2xl font-bold text-white mb-6">Sign In</h2>').join('<h2 style="text-align:center;font-size:24px;font-weight:800;margin:0 0 18px;background:linear-gradient(90deg,#b99aff,#6ec1ff,#ff8ad8);-webkit-background-clip:text;color:transparent">Sign in to Nebula Cloud Play</h2>');
      html=html.split("</head>").join('<style>html{background-image:radial-gradient(1px 1px at 20px 30px,#fff,transparent),radial-gradient(1px 1px at 90px 140px,#cfe,transparent),radial-gradient(1.5px 1.5px at 160px 70px,#fff,transparent),radial-gradient(1px 1px at 60px 200px,#fff,transparent),radial-gradient(1.5px 1.5px at 250px 120px,#dcf,transparent),radial-gradient(1px 1px at 300px 290px,#fff,transparent),radial-gradient(ellipse at 15% 10%,#5b2a9a 0,transparent 50%),radial-gradient(ellipse at 85% 30%,#1b3fa8 0,transparent 50%),radial-gradient(ellipse at 30% 90%,#a02a7a 0,transparent 50%),radial-gradient(ellipse at 90% 95%,#3a1f8a 0,transparent 50%)!important;background-size:220px 220px,220px 220px,220px 220px,340px 340px,340px 340px,340px 340px,auto,auto,auto,auto!important;background-repeat:repeat,repeat,repeat,repeat,repeat,repeat,no-repeat,no-repeat,no-repeat,no-repeat!important;background-color:#07061a!important;background-attachment:fixed!important}body,.portal-body{background:transparent!important}nav{background:rgba(12,8,40,.55)!important;backdrop-filter:blur(14px)!important}.category-btn{background:rgba(255,255,255,.08)!important}.category-btn.active{background:linear-gradient(90deg,#8a5cff,#3fa9ff)!important}#login-modal>div:last-child{background:rgba(18,12,52,.88)!important;backdrop-filter:blur(18px)!important;border-color:rgba(180,150,255,.35)!important;box-shadow:0 0 60px rgba(120,80,255,.35)}#login-submit-btn{background:linear-gradient(90deg,#8a5cff,#3fa9ff)!important}.login-input{background:rgba(10,8,35,.6)!important;border-color:rgba(180,150,255,.3)!important}#login-modal>div:last-child{max-width:420px!important;text-align:center}.nbtn{display:block;width:100%;padding:14px;margin:8px 0;border-radius:999px;border:0;font-weight:700;font-size:15px;cursor:pointer}.nbtn.grad{background:linear-gradient(90deg,#8a5cff,#3fa9ff);color:#fff;border-radius:12px;padding:12px}.nbtn-in{display:block;width:100%;box-sizing:border-box;padding:12px;margin:10px 0 4px;border-radius:12px;border:1px solid rgba(180,150,255,.3);background:rgba(10,8,35,.6);color:#eef}#login-modal .space-y-4{text-align:left}.game-card-item{border-radius:26px!important;border:1px solid rgba(180,150,255,.25)!important;box-shadow:0 8px 30px rgba(10,0,40,.5)!important}.game-card-item:hover{border-color:rgba(138,92,255,.95)!important;box-shadow:0 0 34px rgba(110,193,255,.35),0 0 60px rgba(138,92,255,.35),0 20px 40px rgba(0,0,0,.5)!important}.card-overlay{background:linear-gradient(to top,rgba(24,8,70,.95) 0%,rgba(60,20,120,.35) 45%,transparent 100%)!important}nav{border-bottom:1px solid transparent!important;border-image:linear-gradient(90deg,transparent,#8a5cff,#3fa9ff,#ff8ad8,transparent) 1!important}nav button[class*="8b5cf6"]{background:linear-gradient(90deg,#8a5cff,#3fa9ff)!important;box-shadow:0 0 20px rgba(110,140,255,.5)!important}input[placeholder^="Discovery"]{background:rgba(255,255,255,.07)!important;border-color:rgba(180,150,255,.3)!important;border-radius:999px!important}.category-btn{border-radius:999px!important;backdrop-filter:blur(8px);border:1px solid rgba(180,150,255,.2)!important}.category-btn.active{box-shadow:0 0 18px rgba(110,140,255,.55)}::-webkit-scrollbar-thumb{background:linear-gradient(#8a5cff,#3fa9ff)!important}html,body{overflow:hidden!important;height:100%}nav{position:fixed!important;top:0;left:0;right:0;background:transparent!important;backdrop-filter:none!important;border:0!important;border-image:none!important;padding:18px 28px!important}nav input,nav .group{max-width:340px}#recent-games-section{display:none!important}main{position:fixed!important;left:0;right:0;top:24vh;max-width:none!important;padding:0 30px!important}#game-grid{display:flex!important;flex-direction:row!important;gap:20px!important;overflow-x:auto!important;padding:34px 14px!important;scroll-snap-type:x proximity;scrollbar-width:none}#game-grid::-webkit-scrollbar{display:none}#game-grid .game-card-item{flex:0 0 auto!important;width:min(40vw,210px)!important;aspect-ratio:1/1!important;border-radius:16px!important;scroll-snap-align:start;border:2px solid rgba(255,255,255,.12)!important;box-shadow:0 10px 30px rgba(8,0,40,.55)!important;transition:transform .2s,box-shadow .2s,border-color .2s!important}#game-grid .game-card-item:hover{transform:scale(1.1)!important;border:4px solid #6ec1ff!important;box-shadow:0 0 0 3px rgba(255,255,255,.55),0 0 40px rgba(110,193,255,.65),0 20px 40px rgba(0,0,0,.5)!important}.card-overlay{opacity:0;transition:opacity .2s}.game-card-item:hover .card-overlay{opacity:1}@media (hover:none){.card-overlay{opacity:1}}#category-bar{position:fixed!important;bottom:26px;left:50%;transform:translateX(-50%);width:min(94vw,760px);max-width:none!important;padding:10px 16px!important;border-radius:999px;background:rgba(255,255,255,.1);backdrop-filter:blur(16px);border:1px solid rgba(255,255,255,.2);box-shadow:0 10px 40px rgba(8,0,40,.5)}#neb-clock{position:fixed;top:26px;right:190px;z-index:60;font-weight:700;font-size:18px;color:#eef;text-shadow:0 0 12px rgba(150,120,255,.8)}@media (max-width:700px){#neb-clock{right:auto;left:50%;transform:translateX(-50%);top:70px}}#game-grid .game-card-item.neb-sel{transform:scale(1.1)!important;border:4px solid #6ec1ff!important;box-shadow:0 0 0 3px rgba(255,255,255,.55),0 0 40px rgba(110,193,255,.65),0 20px 40px rgba(0,0,0,.5)!important}.neb-sel .card-overlay{opacity:1!important}#category-bar{box-sizing:border-box!important;flex-wrap:wrap!important;justify-content:center!important;overflow:visible!important;width:min(94vw,1000px)!important;border-radius:30px!important;gap:8px!important}#category-bar .category-btn{padding:6px 14px!important;font-size:13px!important;white-space:nowrap!important;flex:0 0 auto}#login-modal .space-y-4>div:has(#server-select){display:none!important}#server-select{display:none!important}#server-select-container{display:none!important}</style><script>setInterval(function(){var c=document.getElementById("neb-clock");if(c){c.textContent=new Date().toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}},1000);(function(){var i=-1;function cards(){return Array.prototype.slice.call(document.querySelectorAll("#game-grid .game-card-item"))}function open_(id){var m=document.getElementById(id);return m&&m.style.display!==""&&m.style.display!=="none"}function sel(n){var c=cards();if(!c.length)return;n=Math.max(0,Math.min(c.length-1,n));c.forEach(function(x){x.classList.remove("neb-sel")});i=n;var e=c[n];e.classList.add("neb-sel");e.scrollIntoView({behavior:"smooth",inline:"center",block:"nearest"})}document.addEventListener("keydown",function(ev){var t=ev.target&&ev.target.tagName;if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT")return;if(open_("game-modal")||open_("login-modal")||open_("queue-modal"))return;var k=ev.key;if(k==="ArrowRight"||k==="d"||k==="D"){ev.preventDefault();sel(i+1)}else if(k==="ArrowLeft"||k==="a"||k==="A"){ev.preventDefault();sel(i<0?0:i-1)}else if((k==="Enter"||k===" ")&&i>=0){var c=cards()[i];if(c){ev.preventDefault();c.click()}}})})();(function(){function pick(){var z="";try{z=Intl.DateTimeFormat().resolvedOptions().timeZone||""}catch(e){}function has(l){for(var i=0;i<l.length;i++){if(z.indexOf(l[i])===0)return true}return false}if(z.indexOf("America/")===0){var sa=["Sao_Paulo","Argentina","Buenos_Aires","Bogota","Lima","Santiago","Caracas","Montevideo","La_Paz","Asuncion","Guayaquil","Bahia","Fortaleza","Recife","Manaus","Belem","Cuiaba","Campo_Grande"];for(var i=0;i<sa.length;i++){if(z.indexOf(sa[i])>-1)return"21"}var w=["Los_Angeles","Vancouver","Tijuana","Phoenix","Denver","Boise","Edmonton","Anchorage"];for(var j=0;j<w.length;j++){if(z.indexOf(w[j])>-1)return"22"}return"23"}if(z==="Pacific/Honolulu")return"22";if(has(["Europe/","Africa/","Atlantic/","Asia/Istanbul","Asia/Dubai","Asia/Riyadh","Asia/Jerusalem","Asia/Baghdad","Asia/Tehran","Asia/Kuwait","Asia/Qatar"]))return"4";if(has(["Asia/","Australia/","Pacific/","Indian/"]))return"3";return"23"}var g=pick();try{localStorage.setItem("selectedServer",g)}catch(e){}document.addEventListener("DOMContentLoaded",function(){var s=document.getElementById("server-select");if(s)s.value=g})})();<'+'/script></head>');
      html=html.split('</body>').join('<div id="neb-clock"></div></body>');
      document.open();document.write(html);document.close();
    });
  \x3C/script>`;
  const f = document.createElementNS('http://www.w3.org/1999/xhtml','iframe');
  f.style.cssText="position:fixed;top:0;left:0;bottom:0;right:0;width:100%;height:100%;border:none;margin:0;padding:0;overflow:hidden;z-index:999999;";
  $('card').parentNode.appendChild(f); f.srcdoc = l;
  var fk=0,ft=setInterval(function(){try{f.contentWindow.focus()}catch(e){} if(++fk>20)clearInterval(ft)},500);
}
$('t').onclick=()=>{signup=!signup;$('b').textContent=signup?'Sign up':'Log in';$('t').textContent=signup?'Have an account? Log in':'No account? Sign up';$('sub').textContent=signup?'Create your account':'Sign in to continue';err.textContent=''};
$('b').onclick=async()=>{
  const e=$('e').value.trim().toLowerCase(), p=$('p').value;
  if(!/^\S+@\S+\.\S+$/.test(e)) return err.textContent='Enter a valid email';
  if(p.length<6) return err.textContent='Password must be 6+ characters';
  const u=JSON.parse(localStorage.getItem('nebula_users')||'{}'), ph=await h(p);
  if(signup){ if(u[e]) return err.textContent='Account already exists'; u[e]=ph; localStorage.setItem('nebula_users',JSON.stringify(u)); launch(); }
  else { if(u[e]!==ph) return err.textContent='Wrong email or password'; launch(); }
};
if(localStorage.getItem('nebula_in')) launch();
const c=$('c'),x=c.getContext('2d'); let S=[];
function rs(){c.width=innerWidth;c.height=innerHeight;S=Array.from({length:140},()=>({x:Math.random()*c.width,y:Math.random()*c.height,r:Math.random()*1.5+.3,s:Math.random()*.3+.05}))}
rs(); onresize=rs;
(function a(){x.clearRect(0,0,c.width,c.height);x.fillStyle='#fff';S.forEach(s=>{s.y=(s.y+s.s)%c.height;x.globalAlpha=.4+Math.random()*.6;x.beginPath();x.arc(s.x,s.y,s.r,0,7);x.fill()});requestAnimationFrame(a)})();
